arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF9 breaking change: Migrate() can no longer be called within a user transaction.
    // The migration infrastructure now manages its own transactions internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            // Removed: BeginTransaction() / Commit() wrapper — EF9 throws
            // InvalidOperationException if Migrate() is called inside a transaction.
            db.Database.Migrate();
        });
    }
}

